/* Sade: ağ geçişi bütün ekrandır, gerisini yazı yapar. Yazı optik merkezde durur; müşteriler alt kenarı tutar. */
.hero { isolation: isolate; display: grid; }
.mesh {
  --mesh-base: #eceef3;
  --mesh-1: #bdd3ec; --mesh-2: #c3c6ff; --mesh-3: #d8e4f7; --mesh-4: #f6bfd6; --mesh-5: #cfe8dc; --mesh-6: #eef1fb;
  z-index: -1;
}
:global(:root[data-theme="dark"]) .mesh {
  --mesh-base: #09090f;
  --mesh-1: #0d3a47; --mesh-2: #2a2f86; --mesh-3: #5a2a3c; --mesh-4: #3a1f5a; --mesh-5: #1f4a5c; --mesh-6: #12142c;
}
/* Temaya duyarlı bir perde, ağ nereye kayarsa kaysın gövde metnini 4,5:1 üstünde tutar. */
.hero::after { content: ""; position: absolute; z-index: -1; inset: 0; background: linear-gradient(to bottom, transparent 40%, color-mix(in oklab, var(--background) 22%, transparent)); pointer-events: none; }

.inner { display: grid; box-sizing: border-box; width: 100%; max-width: 1320px; grid-template-rows: 1fr auto auto 1fr auto; gap: var(--space-10); margin: 0 auto; padding: clamp(88px, 12svh, 128px) var(--space-10) var(--space-10); }
.title { grid-row: 2; }
.row { grid-row: 3; }
.brands { grid-row: 5; }
.title { max-width: 14ch; font-size: clamp(2.75rem, 1rem + 7cqi, 7rem); }
.row { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: var(--space-8) var(--space-16); }
.description { max-width: 520px; color: color-mix(in oklab, var(--foreground) 76%, transparent); }
.cta { display: grid; justify-items: end; gap: var(--space-3); }
.actions { display: flex; flex-wrap: wrap; gap: var(--space-3); }
.fine { margin: 0; color: color-mix(in oklab, var(--foreground) 62%, transparent); font-size: var(--text-sm); }

.brands { display: grid; gap: var(--space-5); border-top: 1px solid color-mix(in oklab, var(--foreground) 14%, transparent); padding-top: var(--space-6); }
.brands p { margin: 0; color: color-mix(in oklab, var(--foreground) 62%, transparent); font-size: var(--text-sm); }
.brands ul { display: flex; flex-wrap: wrap; justify-content: space-between; gap: var(--space-5) var(--space-8); margin: 0; padding: 0; list-style: none; }
.brands li { display: inline-flex; align-items: center; gap: 9px; color: color-mix(in oklab, var(--foreground) 78%, transparent); font-size: var(--text-lg); font-weight: 500; letter-spacing: var(--tracking-body); }
.brands svg { flex: none; width: 22px; height: 22px; }

@container hero (max-width: 800px) {
  .row { grid-template-columns: minmax(0, 1fr); align-items: start; }
  .cta { justify-items: start; }
  .brands ul { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@container hero (max-width: 560px) {
  .inner { gap: var(--space-6); padding: 80px var(--space-4) var(--space-6); }
  .actions { width: 100%; }
  .actions > * { flex: 1 1 auto; }
  .cta { width: 100%; }
  .brands ul { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-4) var(--space-3); }
  .brands li:nth-child(n + 7) { display: none; }
  .brands li { font-size: var(--text-base); }
  .brands svg { width: 18px; height: 18px; }
}

"use client";

import { MotionConfig, motion } from "motion/react";
import { Circle, Diamond, Hexagon, Pentagon, Square, Star, Triangle } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { ActionLink } from "./hero-content";
import type { HeroAction } from "./hero-content";
import { HeroMesh } from "./hero-mesh";
import type { HeroMeshPoint } from "./hero-mesh";
import { heroGroup, heroRise } from "./hero-motion";
import shell from "./hero-section.module.css";
import styles from "./hero-cadence.module.css";

export interface HeroCadenceProps {
  primaryAction?: HeroAction | undefined;
  secondaryAction?: HeroAction | undefined;
  animateIn?: boolean | undefined;
  className?: string | undefined;
}

/** Altı nokta, Gradient mesh düzenleyicisinin kaydettiği biçimde yazılmış. Renkler CSS'te durur, her tema için bir palet. */
const MESH: HeroMeshPoint[] = [
  { x: .1, y: .88, spread: .72 },
  { x: .86, y: .12, spread: .66 },
  { x: .16, y: .14, spread: .56 },
  { x: .62, y: .62, spread: .5 },
  { x: .94, y: .92, spread: .48 },
  { x: .44, y: .3, spread: .34 },
];

/** Örnek müşteriler. Şirket adları uydurmadır; işaretler genel şekillerdir ve metin renginde çizilir. */
const BRANDS: { name: string; Icon: LucideIcon }[] = [
  { name: "Kuzey Lojistik", Icon: Hexagon },
  { name: "Marmara Gıda", Icon: Circle },
  { name: "Anadolu Yapı", Icon: Triangle },
  { name: "Ege Tekstil", Icon: Square },
  { name: "Toros Enerji", Icon: Diamond },
  { name: "Karadeniz Tarım", Icon: Pentagon },
  { name: "Trakya Medya", Icon: Star },
];

/** Sade hero, tam ekran: yavaşça akan, greni olan bir ağ geçişi üstünde büyük yazı ve alt kenarda ürünü kullanan ekipler. */
export function HeroCadence({ primaryAction = { label: "Mac için indir", doneLabel: "İndirme başladı" }, secondaryAction = { label: "Web'de dene", doneLabel: "Ritim açılıyor" }, animateIn = true, className }: HeroCadenceProps) {
  const item = heroRise;
  // Azaltılmış hareket: Motion her dönüşümü atlar (yükselme, yakınlaşma, eğim girişi); opaklık yine kısaca solar.
  return <MotionConfig reducedMotion="user"><section className={[shell.hero, shell.screen, styles.hero, className].filter(Boolean).join(" ")}>
    <HeroMesh className={styles.mesh} points={MESH} grain={.55} speed={.45} />
    <motion.div className={styles.inner} variants={heroGroup} initial={animateIn ? "hidden" : false} animate="shown">
      <motion.h1 variants={item} className={[shell.title, styles.title].join(" ")}>Haftanız, pazartesiden önce planlı</motion.h1>
      <div className={styles.row}>
        <motion.p variants={item} className={[shell.description, styles.description].join(" ")}>Ritim görevlerinizi, toplantılarınızı ve odak hedeflerinizi okur, sonra önemli işe zaman ayırır. Planlar değişince her şeyi sizin yerinize taşır.</motion.p>
        <motion.div variants={item} className={styles.cta}>
          <div className={styles.actions}>
            <ActionLink action={primaryAction} kind="primary" />
            <ActionLink action={secondaryAction} kind="secondary" />
          </div>
          <p className={styles.fine}>Kişisel kullanım ücretsiz. Ekipler için kişi başı aylık ₺290&apos;dan.</p>
        </motion.div>
      </div>
      <motion.div variants={item} className={styles.brands}>
        <p>Bu şirketlerin ekipleri Ritim ile planlıyor</p>
        <ul aria-label="Örnek müşteriler">
          {BRANDS.map(({ name, Icon }) => <li key={name}><Icon size={20} strokeWidth={1.75} aria-hidden="true" />{name}</li>)}
        </ul>
      </motion.div>
    </motion.div>
  </section></MotionConfig>;
}

export default HeroCadence;

.inner { display: grid; max-width: 1200px; margin: 0 auto; padding: var(--space-24) var(--space-10); }
.copy { display: grid; grid-template-columns: minmax(0, 1fr); justify-items: center; gap: var(--space-5); max-width: 760px; margin: 0 auto; text-align: center; }
.title { max-width: 16ch; }
.description { max-width: 560px; }

.announcement { display: inline-flex; max-width: 100%; min-height: 32px; align-items: center; gap: 6px; border: 1px solid var(--border); border-radius: var(--radius-pill); padding: 4px var(--space-3); background: var(--surface); color: var(--text-secondary); font: inherit; font-size: var(--text-sm); text-align: left; text-decoration: none; cursor: pointer; transition: color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard); }
.arrow { flex: none; transition: transform var(--duration-fast) var(--ease-standard); }

.actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--space-3); margin-top: var(--space-3); }
.action { display: inline-flex; height: var(--control-height-md); align-items: center; justify-content: center; gap: var(--space-2); border: 1px solid transparent; border-radius: var(--radius-control); padding: 0 var(--space-5); font: inherit; font-size: var(--text-sm); font-weight: 500; text-decoration: none; white-space: nowrap; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: transform var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard), opacity var(--duration-fast) var(--ease-standard); }
.action:active { transform: scale(.97); }
.primary { background: var(--foreground); color: var(--background); }
.secondary { border-color: var(--border); background: var(--surface); color: var(--foreground); }
@media (hover: hover) and (pointer: fine) {
  .primary:hover { opacity: .9; }
  .secondary:hover { background: var(--surface-muted); }
  .announcement:hover { border-color: var(--border-strong); color: var(--foreground); }
  :is(.action, .announcement):hover .arrow { transform: translateX(2px); }
}

.install { display: flex; width: min(100%, 440px); height: var(--control-height-md); align-items: center; gap: var(--space-2); margin-top: var(--space-2); border: 1px solid var(--border); border-radius: var(--radius-control); padding: 0 var(--space-1) 0 var(--space-4); background: var(--surface); font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 13px; text-align: left; }
.prompt { color: var(--text-muted); }
.command { flex: 1; overflow: hidden; color: var(--foreground); font: inherit; text-overflow: ellipsis; white-space: nowrap; }

.meta { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-5); margin: var(--space-4) 0 0; border-top: 1px solid var(--border-subtle); padding: var(--space-5) 0 0; color: var(--text-muted); font-size: var(--text-sm); list-style: none; }

.media { min-width: 0; }

.split .inner { grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr); align-items: center; gap: var(--space-12); }
.split .copy, .minimal .copy { justify-items: start; margin: 0; text-align: left; }
.split .actions, .minimal .actions { justify-content: flex-start; }
.minimal .copy { max-width: 860px; }

@container hero (max-width: 800px) {
  .split .inner { grid-template-columns: minmax(0, 1fr); gap: var(--space-10); }
}
@container hero (max-width: 560px) {
  .inner { padding: var(--space-16) var(--space-4); }
  .actions { width: 100%; }
  .action { flex: 1 1 auto; }
}

@media (prefers-reduced-motion: reduce) {
  .action, .announcement, .arrow { transition: none; }
  .action:active { transform: none; }
}

/* Düğmeler katalog düğmeleridir; bu yalnız onları yanlarındaki bağlantı eylemlerinin yüksekliğinde tutar. */
.button { height: var(--control-height-md); min-height: var(--control-height-md); border-radius: var(--radius-control); font-size: var(--text-sm); }

"use client";

import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import { MotionConfig, motion } from "motion/react";
import { ArrowRight, ArrowUpRight, Check } from "lucide-react";
import { Button } from "../button/button";
import { CopyButton } from "../copy-button/copy-button";
import { heroGroup, heroRise } from "./hero-motion";
import shell from "./hero-section.module.css";
import styles from "./hero-content.module.css";

export interface HeroAction {
  label: string;
  href?: string | undefined;
  onClick?: (() => void) | undefined;
  /** Yeni sekmede açar ve dışa bakan bir ok gösterir. */
  external?: boolean | undefined;
  /** Basıştan sonra bir an etiketin yerinde görünür, örneğin "Deneme başladı". Yalnız düğmelerde. */
  doneLabel?: string | undefined;
}

export interface HeroInstallCommand {
  /** Kısa etiket, örneğin npm ya da pnpm. İlk komut gösterilir. */
  label: string;
  command: string;
}

export interface HeroContentProps {
  layout: "centered" | "split" | "minimal";
  announcement?: HeroAction | null | undefined;
  title: string;
  description?: string | undefined;
  primaryAction?: HeroAction | null | undefined;
  secondaryAction?: HeroAction | null | undefined;
  install?: HeroInstallCommand[] | null | undefined;
  media?: ReactNode | undefined;
  meta?: string[] | undefined;
  animateIn?: boolean | undefined;
  className?: string | undefined;
}

/** Düğme görünümlü bir bağlantı ya da düğme. Bağlantılar yerel gezinmeyi korur; `doneLabel` taşıyan düğme yerinde onaylar. */
export function ActionLink({ action, kind, className }: { action: HeroAction; kind: "primary" | "secondary"; className?: string | undefined }) {
  const [done, setDone] = useState(false);
  useEffect(() => {
    if (!done) return;
    const timer = window.setTimeout(() => setDone(false), 2400);
    return () => window.clearTimeout(timer);
  }, [done]);
  const cls = [styles.action, styles[kind], className].filter(Boolean).join(" ");
  const icon = action.external ? <ArrowUpRight size={16} strokeWidth={1.75} aria-hidden="true" /> : kind === "primary" ? <ArrowRight className={styles.arrow} size={16} strokeWidth={1.75} aria-hidden="true" /> : null;
  if (action.href) return <a className={cls} href={action.href} onClick={action.onClick} {...(action.external ? { target: "_blank", rel: "noopener noreferrer" } : {})}>{action.label}{icon}</a>;
  return <Button variant={kind} size="lg" className={[styles.button, className].filter(Boolean).join(" ")} onClick={() => { action.onClick?.(); if (action.doneLabel) setDone(true); }}>
    {done ? <><Check size={16} strokeWidth={1.75} aria-hidden="true" />{action.doneLabel}</> : <>{action.label}{icon}</>}
  </Button>;
}

/**
 * Kendi içeriğinizle hero: duyuru, başlık, açıklama, çağrılar, isteğe bağlı kurulum satırı ve yazının yanında isteğe bağlı bir
 * görsel. Tasarlanmış üç çeşitten hiçbiri ürüne uymuyorsa kullanın.
 */
export function HeroContent({ layout, announcement, title, description, primaryAction, secondaryAction, install, media, meta, animateIn = true, className }: HeroContentProps) {
  const item = heroRise;
  const command = install?.[0];
  // Azaltılmış hareket: Motion her dönüşümü atlar (yükselme, yakınlaşma, eğim girişi); opaklık yine kısaca solar.
  return <MotionConfig reducedMotion="user"><section className={[shell.hero, styles.hero, styles[layout], className].filter(Boolean).join(" ")}>
    <div className={styles.inner}>
      <motion.div className={styles.copy} variants={heroGroup} initial={animateIn ? "hidden" : false} animate="shown">
        {announcement && <motion.div variants={item}>
          {announcement.href
            ? <a className={styles.announcement} href={announcement.href} onClick={announcement.onClick}>{announcement.label}<ArrowRight className={styles.arrow} size={14} strokeWidth={1.75} aria-hidden="true" /></a>
            : <button type="button" className={styles.announcement} onClick={announcement.onClick}>{announcement.label}<ArrowRight className={styles.arrow} size={14} strokeWidth={1.75} aria-hidden="true" /></button>}
        </motion.div>}
        <motion.h1 variants={item} className={[shell.title, styles.title].join(" ")}>{title}</motion.h1>
        {description && <motion.p variants={item} className={[shell.description, styles.description].join(" ")}>{description}</motion.p>}
        {(primaryAction || secondaryAction) && <motion.div variants={item} className={styles.actions}>
          {primaryAction && <ActionLink action={primaryAction} kind="primary" />}
          {secondaryAction && <ActionLink action={secondaryAction} kind="secondary" />}
        </motion.div>}
        {command && <motion.div variants={item} className={styles.install}>
          <span className={styles.prompt} aria-hidden="true">$</span>
          <code className={styles.command}>{command.command}</code>
          <CopyButton value={command.command} label="Kurulum komutunu kopyala" iconOnly variant="plain" />
        </motion.div>}
        {meta && meta.length > 0 && <motion.ul variants={item} className={styles.meta}>{meta.map(entry => <li key={entry}>{entry}</li>)}</motion.ul>}
      </motion.div>
      {media && <motion.div className={styles.media} variants={item} initial={animateIn ? "hidden" : false} animate="shown">{media}</motion.div>}
    </div>
  </section></MotionConfig>;
}

export default HeroContent;

import { date } from "@snn/abacus-core";
import type { LineChartDatum } from "../line-chart/line-chart";

/** Parıltı için örnek veri: bir gelir analitiği ürünü. Yerine kendi ürününüzün sayılarını koyun. */

export type LumenRange = "30d" | "90d" | "12m";

export const lumenRanges: { value: LumenRange; label: string }[] = [
  { value: "30d", label: "30G" },
  { value: "90d", label: "90G" },
  { value: "12m", label: "12A" },
];

/** Düzgün, belirleyici bir yürüyüş: bir eğilim, yavaş bir dalga ve aynı tohum için tekrar eden küçük bir gürültü. */
function walk(count: number, start: number, end: number, wave: number, seed: number) {
  let s = seed;
  const rand = () => { s = (s * 16807) % 2147483647; return s / 2147483647 - .5; };
  return Array.from({ length: count }, (_, i) => {
    const t = i / (count - 1);
    return Math.round(start + (end - start) * (t * t * .35 + t * .65) + Math.sin(t * Math.PI * 2.3) * wave + rand() * wave * .6);
  });
}

const months = ["Eki", "Kas", "Ara", "Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl"];

function series(range: LumenRange): LineChartDatum[] {
  if (range === "12m") {
    const now = walk(12, 9_800, 36_400, 2_600, 7), before = walk(12, 6_200, 21_900, 2_200, 19);
    return months.map((month, i) => ({ key: `m${i}`, label: `${month} ${i < 3 ? 2025 : 2026}`, axisLabel: i % 2 === 0 ? month : undefined, values: { mrr: now[i], last: before[i] } }));
  }
  const days = range === "30d" ? 30 : 13;
  const step = range === "30d" ? 1 : 7;
  const now = walk(days, range === "30d" ? 640 : 4_300, range === "30d" ? 1_960 : 9_800, range === "30d" ? 260 : 900, range === "30d" ? 3 : 11);
  const before = walk(days, range === "30d" ? 520 : 3_600, range === "30d" ? 1_180 : 6_100, range === "30d" ? 220 : 700, 29);
  const end = new Date(Date.UTC(2026, 8, 24));
  return now.map((value, i) => {
    const day = new Date(end.getTime() - (days - 1 - i) * step * 86_400_000);
    const iso = day.toISOString().slice(0, 10);
    const label = date.format(iso, "dayMonth");
    const every = range === "30d" ? 7 : 3;
    return { key: iso, label, axisLabel: (days - 1 - i) % every === 0 ? label : undefined, values: { mrr: value, last: before[i] } };
  });
}

export const lumenSeries: Record<LumenRange, LineChartDatum[]> = { "30d": series("30d"), "90d": series("90d"), "12m": series("12m") };

export interface LumenKpi {
  id: string;
  label: string;
  tone: "accent" | "success" | "warning" | "danger";
  byRange: Record<LumenRange, { value: string; change: string; data: number[] }>;
}

export const lumenKpis: LumenKpi[] = [
  { id: "mrr", label: "Aylık yinelenen gelir", tone: "accent", byRange: {
    "30d": { value: "₺482,9B", change: "+%8,2", data: walk(12, 446, 483, 4, 5) },
    "90d": { value: "₺482,9B", change: "+%19,9", data: walk(12, 402, 483, 6, 9) },
    "12m": { value: "₺482,9B", change: "+%51,7", data: walk(12, 318, 483, 8, 13) },
  } },
  { id: "nrr", label: "Net elde tutma", tone: "success", byRange: {
    "30d": { value: "%118", change: "+3 puan", data: walk(12, 112, 118, 1.5, 17) },
    "90d": { value: "%116", change: "+5 puan", data: walk(12, 109, 116, 1.8, 21) },
    "12m": { value: "%114", change: "+9 puan", data: walk(12, 103, 114, 2.4, 23) },
  } },
  { id: "new", label: "Yeni müşteri", tone: "success", byRange: {
    "30d": { value: "214", change: "+%12", data: walk(12, 5, 9, 2, 31) },
    "90d": { value: "602", change: "+%18", data: walk(12, 38, 56, 6, 37) },
    "12m": { value: "2.140", change: "+%34", data: walk(12, 120, 214, 16, 41) },
  } },
  { id: "churn", label: "Kaybedilen gelir", tone: "success", byRange: {
    "30d": { value: "₺6,1B", change: "−%14", data: walk(12, 9, 6, 1.2, 43) },
    "90d": { value: "₺21,4B", change: "−%9", data: walk(12, 26, 21, 2, 47) },
    "12m": { value: "₺96,8B", change: "−%22", data: walk(12, 12, 7, 1.4, 53) },
  } },
];

export interface LumenMover {
  name: string;
  change: string;
  amount: number;
}

/** Örnek müşteriler: şirket adları uydurmadır. Her birinin başında adının baş harfi çizilir. */
export const lumenMovers: LumenMover[] = [
  { name: "Kuzey Lojistik", change: "Kurumsal plana geçti", amount: 4_200 },
  { name: "Marmara Gıda", change: "120 koltuk ekledi", amount: 2_850 },
  { name: "Anadolu Yapı", change: "Yıllık ön ödeme", amount: 1_900 },
  { name: "Ege Tekstil", change: "40 koltuk kaldırdı", amount: -1_240 },
  { name: "Toros Enerji", change: "Tahmin modülünü ekledi", amount: 980 },
  { name: "Karadeniz Tarım", change: "Büyüme planına yükseldi", amount: 760 },
];

export const lumenInsight: Record<LumenRange, { lead: string; rest: string }> = {
  "30d": { lead: "Aylık gelir bu ay ₺36,4B büyüdü.", rest: "%62'si Büyüme planındaki 14 genişlemeden geldi; başta Kuzey Lojistik." },
  "90d": { lead: "Aylık gelir bu çeyrekte ₺80,6B büyüdü.", rest: "Genişleme, Mart'tan beri ilk kez yeni müşteriyi geçti." },
  "12m": { lead: "Aylık gelir on iki ayda ₺164,5B büyüdü.", rest: "%110'un üstündeki net elde tutma, yeni müşterilerden fazlasını yaptı." },
};

/* Ortalı, tam ekran: akan bir ağın üstünde yazı ve alt kenardan yükselip ondan taşan bir ürün penceresi.
   Hero tam bir ekran boyundadır (600px'ten kısa olmaz); pencere yazının bıraktığı yüksekliği alır. */
/* Bölümün kendisi kaptır; yan boşlukları çocukları taşır ve aşağıdaki sorgular bunları değiştirebilir. */
.hero { isolation: isolate; display: flex; height: 100vh; height: 100svh; min-height: 600px; flex-direction: column; padding-top: clamp(88px, 14svh, 144px); text-align: center; }

/* Ağ bütün ekranı doldurur. Her tema için ayrı yazılmıştır: sayfadan birkaç basamak ayrı tonlar, renk değil ışık gibi okunur. */
.mesh {
  --mesh-base: var(--background);
  --mesh-1: #e1ecff; --mesh-2: #e3dcff; --mesh-3: #dbe4ff; --mesh-4: #f0e0ff; --mesh-5: #e0eefc;
  z-index: -1;
}
:global(:root[data-theme="dark"]) .mesh { --mesh-1: #2a1822; --mesh-2: #1c1a44; --mesh-3: #141c40; --mesh-4: #231842; --mesh-5: #0e2133; }

.copy { position: relative; display: grid; justify-items: center; gap: var(--space-5); max-width: 900px; margin: 0 auto; padding-inline: var(--space-10); }
.title { max-width: 14ch; font-size: clamp(2.5rem, 1.2rem + 5cqi, var(--text-5xl)); }
.description { max-width: 590px; }
.actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--space-3); margin-top: var(--space-3); }
.fine { margin: 0; color: var(--text-muted); font-size: var(--text-sm); }

/* Sahne: ekranın kalanını doldurur ve görünen kırpmadır. Pencere alt kenarından taşar; maske onu ağa doğru eritir, böylece sert
   kenar kalmaz. Üstteki hale, pencerenin arkasındaki ışığa yer bırakır. */
.stage { --halo: 96px; position: relative; flex: 1 1 0; box-sizing: border-box; width: 100%; min-height: 0; max-width: calc(1200px + 2 * var(--space-10)); margin: calc(var(--space-12) - var(--halo)) auto 0; overflow: hidden; padding: var(--halo) var(--space-10) 0; -webkit-mask-image: linear-gradient(to bottom, #000 62%, transparent 100%); mask-image: linear-gradient(to bottom, #000 62%, transparent 100%); }
.glow {
  position: absolute; z-index: -1; top: calc(var(--halo) - 110px); left: 10%; right: 10%; height: 240px;
  background: radial-gradient(50% 50% at 50% 50%, var(--hero-glow), transparent 72%);
  filter: blur(36px);
  --hero-glow: color-mix(in oklab, color-mix(in oklab, var(--accent) 35%, #7d8cff) 36%, transparent);
}
:global(:root[data-theme="dark"]) .glow { --hero-glow: color-mix(in oklab, color-mix(in oklab, var(--accent) 30%, #6e7cff) 58%, transparent); }
.window { position: relative; }
/* İnce bir ışık, gerçek bir ekranın karanlık odada yaptığı gibi üst kenarı yakalar. */
:global(:root[data-theme="dark"]) .window::after { content: ""; position: absolute; top: 0; left: 12%; right: 12%; height: 1px; background: linear-gradient(to right, transparent, color-mix(in oklab, #b9c2ff 70%, transparent), transparent); pointer-events: none; }
.perspective { display: flex; justify-content: center; perspective: 2200px; perspective-origin: 50% 0%; }
.tilt { position: relative; flex: none; transform-origin: 50% 0%; will-change: transform; }
.scaler { position: absolute; top: 0; left: 0; transform-origin: 0 0; }
/* Azaltılmış hareket: pencere yerindedir; giriş için tutulan GPU katmanı bırakılır. */
@media (prefers-reduced-motion: reduce) { .tilt { will-change: auto; } }

/* Pencere. */
.window {
  display: grid; grid-template-rows: auto minmax(0, 1fr); height: 100%; overflow: hidden;
  border: 1px solid var(--border); border-radius: 16px; background: var(--surface); color: var(--foreground);
  text-align: left; font-size: var(--text-sm);
  box-shadow: 0 1px 1px rgb(20 24 40 / .04), 0 24px 48px -16px rgb(20 24 40 / .16), 0 60px 120px -40px rgb(40 48 110 / .22);
}
:global(:root[data-theme="dark"]) .window {
  border-color: color-mix(in oklab, var(--foreground) 14%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--foreground) 9%, transparent), 0 24px 48px -16px rgb(0 0 0 / .6), 0 60px 140px -40px rgb(40 50 140 / .35);
}
.chrome { position: relative; display: flex; height: 40px; align-items: center; justify-content: center; border-bottom: 1px solid var(--border-subtle); background: color-mix(in oklab, var(--surface-muted) 55%, var(--surface)); }
.lights { position: absolute; left: 16px; display: flex; gap: 7px; }
.lights i { width: 11px; height: 11px; border-radius: 50%; background: color-mix(in oklab, var(--foreground) 14%, transparent); }
.url { border-radius: 8px; padding: 3px 14px; background: var(--surface); color: var(--text-muted); font-size: var(--text-xs); box-shadow: inset 0 0 0 1px var(--border-subtle); }

.app { display: grid; grid-template-columns: 224px minmax(0, 1fr); min-height: 0; }
.window[data-narrow] .app { grid-template-columns: minmax(0, 1fr); }

.sidebar { display: flex; flex-direction: column; gap: 2px; border-right: 1px solid var(--border-subtle); padding: 14px 12px; background: color-mix(in oklab, var(--surface-muted) 40%, var(--surface)); }
.workspace { display: flex; align-items: center; gap: 10px; padding: 6px 8px 10px; }
.wsMark { display: grid; width: 22px; height: 22px; place-items: center; border-radius: 6px; background: var(--foreground); color: var(--background); font-size: var(--text-xs); font-weight: 500; }
.wsName { flex: 1; font-weight: 500; }
.dim { color: var(--text-muted); }
.search { display: flex; align-items: center; gap: 8px; margin: 0 0 10px; border: 1px solid var(--border-subtle); border-radius: 9px; padding: 6px 8px; background: var(--surface); color: var(--text-muted); }
.search kbd { margin-left: auto; font: inherit; font-size: var(--text-xs); }
.nav { display: grid; gap: 1px; }
.navItem { display: flex; align-items: center; gap: 10px; border-radius: 8px; padding: 6px 8px; color: var(--text-secondary); }
.navItem svg { color: var(--text-muted); }
.navItem[data-active] { background: var(--accent-subtle); color: var(--foreground); font-weight: 500; }
.navItem[data-active] svg { color: var(--accent); }
.groupLabel { margin: 18px 8px 6px; color: var(--text-muted); font-size: var(--text-xs); }
.dot { width: 8px; height: 8px; margin: 0 3px; border-radius: 50%; background: var(--text-muted); }
.dot[data-tone="accent"] { background: var(--accent); }
.dot[data-tone="danger"] { background: var(--danger); }
.me { display: flex; align-items: center; gap: 10px; margin-top: auto; border-top: 1px solid var(--border-subtle); padding: 12px 6px 2px; }
.me span:not([role]) { display: grid; flex: 1; line-height: 1.3; }
.me strong { font-weight: 500; }
.me small { color: var(--text-muted); font-size: var(--text-xs); }

.main { display: grid; align-content: start; gap: 16px; min-width: 0; padding: 22px 24px; }
.head { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.h2 { margin: 0; font-size: var(--text-lg); font-weight: 500; letter-spacing: var(--tracking-body); }
.sub { margin: 2px 0 0; color: var(--text-muted); font-size: var(--text-xs); }
.range { flex: none; }

.kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.window[data-narrow] .kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.kpi { min-width: 0; border: 1px solid var(--border-subtle); border-radius: 12px; padding: 14px 16px 12px; background: var(--surface); }

.grid { display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr); gap: 12px; }
.window[data-narrow] .grid { grid-template-columns: minmax(0, 1fr); }
.card { display: grid; align-content: start; gap: 14px; min-width: 0; border: 1px solid var(--border-subtle); border-radius: 12px; padding: 16px 18px; background: var(--surface); }
.cardHead { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.insight { display: flex; gap: 8px; max-width: 46ch; margin: 0; color: var(--text-secondary); line-height: 1.45; }
.insight strong { color: var(--foreground); font-weight: 500; }
.insightIcon { flex: none; margin-top: 2px; color: var(--accent); }
.legend { display: flex; flex: none; gap: 14px; color: var(--text-muted); font-size: var(--text-xs); }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.swatch { width: 14px; height: 2px; border-radius: 2px; background: var(--accent); }
.swatch[data-last] { background: repeating-linear-gradient(to right, color-mix(in oklab, var(--foreground) 46%, var(--surface)) 0 4px, transparent 4px 7px); }
.window[data-narrow] .legend { display: none; }

.cardTitle { display: flex; justify-content: space-between; font-weight: 500; }
.cardTitle span { color: var(--text-muted); font-size: var(--text-xs); font-weight: 400; }
.movers { display: grid; margin: 0; padding: 0; list-style: none; }
.movers li { display: flex; align-items: center; gap: 12px; border-top: 1px solid var(--border-subtle); padding: 10px 0; }
.movers li:first-child { border-top: 0; padding-top: 2px; }
.mark { display: grid; flex: none; width: 24px; height: 24px; place-items: center; border-radius: 7px; background: var(--accent-subtle); color: var(--accent); font-size: var(--text-xs); font-weight: 600; }
.who { display: grid; flex: 1; min-width: 0; line-height: 1.3; }
.who strong { font-weight: 500; }
.who small { overflow: hidden; color: var(--text-muted); font-size: var(--text-xs); text-overflow: ellipsis; white-space: nowrap; }
.amount { color: var(--success); font-variant-numeric: tabular-nums; font-weight: 500; }
.amount[data-down] { color: var(--danger); }

@container hero (max-width: 560px) {
  .hero { padding-top: 84px; }
  .copy { gap: var(--space-4); padding-inline: var(--space-4); }
  .actions { width: 100%; margin-top: var(--space-2); }
  .actions > * { flex: 1 1 auto; }
  .stage { --halo: 56px; margin-top: calc(var(--space-10) - var(--halo)); padding-inline: 0; }
}

/* KPI kutuları Sparkline bileşenini kullanır; başlığı sarar, böylece etiket daha büyük değerin üstünde durur. */
.kpi :global(figcaption) { flex-wrap: wrap; row-gap: 4px; }
.kpi :global(figcaption) > :first-child { flex-basis: 100%; font-size: var(--text-xs); color: var(--text-muted); }
.kpi :global(figcaption) strong { margin-left: 0; font-size: var(--text-2xl); letter-spacing: var(--tracking-body); }
.kpi :global(figcaption) small { align-self: center; }

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import { MotionConfig, motion, useReducedMotion } from "motion/react";
import { BarChart3, BookOpen, ChevronsUpDown, Gauge, LineChart as LineIcon, Search, Settings, Sparkles, Users } from "lucide-react";
import { money } from "@snn/abacus-core";
import { LineChart } from "../line-chart/line-chart";
import { Sparkline } from "../sparkline/sparkline";
import SegmentedControl from "../segmented-control/segmented-control";
import { Avatar } from "../avatar/avatar";
import { avatarInitials } from "../avatar/avatar-initials";
import { motionTokens } from "../lib/motion-tokens";
import { ActionLink } from "./hero-content";
import type { HeroAction } from "./hero-content";
import { HeroMesh } from "./hero-mesh";
import type { HeroMeshPoint } from "./hero-mesh";
import { heroGroup, heroRise } from "./hero-motion";
import { lumenInsight, lumenKpis, lumenMovers, lumenRanges, lumenSeries } from "./hero-lumen-data";
import type { LumenRange } from "./hero-lumen-data";
import shell from "./hero-section.module.css";
import styles from "./hero-lumen.module.css";

/** Bütün ekranda yumuşak bir ağ: üstte serin tonlar, pencerenin arkasında alçakta bir ton; hepsi sayfadan birkaç basamak ayrı. */
const MESH: HeroMeshPoint[] = [
  { x: .1, y: .92, spread: .7 },
  { x: .92, y: .86, spread: .66 },
  { x: .14, y: .08, spread: .64 },
  { x: .86, y: .04, spread: .6 },
  { x: .5, y: .38, spread: .46 },
];

const NAV = [
  { label: "Genel bakış", icon: Gauge, active: true },
  { label: "Gelir", icon: LineIcon },
  { label: "Müşteriler", icon: Users },
  { label: "Kohortlar", icon: BarChart3 },
  { label: "Tahminler", icon: Sparkles },
  { label: "Raporlar", icon: BookOpen },
];
const VIEWS = [{ label: "Kurumsal genişleme", tone: "accent" }, { label: "Kayıp riski", tone: "danger" }, { label: "Avrupa müşterileri", tone: "neutral" }];

const formatMoney = (value: number) => money.formatMajor(value, { currency: "TRY", digits: 0 });
const compact = (value: number) => money.compactMajor(value, { currency: "TRY", style: "B/Mn/Mr", digits: 1 });

/** Panonun tasarlandığı genişlik, geniş ve dar. O boyutta çizilir ve ekran görüntüsü gibi sığacak kadar ölçeklenir. */
const WIDE = 1200, NARROW = 600;

export interface HeroLumenProps {
  primaryAction?: HeroAction | undefined;
  secondaryAction?: HeroAction | undefined;
  animateIn?: boolean | undefined;
  /** Panonun kenar çubuğundaki kişinin adı. */
  userName?: string | undefined;
  /** Kişinin unvanı. */
  userRole?: string | undefined;
  /** Kişinin fotoğrafı. Verilmezse Avatar baş harflere döner. */
  userAvatarSrc?: string | undefined;
  className?: string | undefined;
}

/**
 * Ortalı hero, tam ekran: akan bir ağın üstünde başlık ve alt kenardan yükselen canlı bir gelir panosu. Pencere eğimden
 * yerine oturarak girer ve ekranın altından solarak taşar. Gerçek işaretlemedir, grafik bileşenlerinden kurulmuştur;
 * aralık denetimi çalışır.
 */
export function HeroLumen({ primaryAction = { label: "Ücretsiz denemeyi başlat", doneLabel: "Deneme başladı" }, secondaryAction = { label: "Demo planla", doneLabel: "Demo istendi" }, animateIn = true, userName = "Elif Yıldız", userRole = "Veri analisti", userAvatarSrc, className }: HeroLumenProps) {
  const calm = !!useReducedMotion();
  const item = heroRise;
  const stage = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState({ width: WIDE, scale: 1 });

  useLayoutEffect(() => {
    const node = stage.current;
    if (!node) return;
    const measure = () => {
      const css = getComputedStyle(node);
      const width = node.clientWidth - parseFloat(css.paddingLeft) - parseFloat(css.paddingRight);
      const design = width < 720 ? NARROW : WIDE;
      // Telefonda pencere okunur boyutta kalır ve sığmak için küçülmek yerine iki kenardan eşit kırpılır.
      setBox({ width: design, scale: design === NARROW ? Math.max(.6, Math.min(1, width / design)) : Math.min(1, width / design) });
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  const narrow = box.width === NARROW;
  const height = narrow ? 700 : 760;

  // Azaltılmış hareket: Motion her dönüşümü atlar (yükselme, yakınlaşma, eğim girişi); opaklık yine kısaca solar.
  return <MotionConfig reducedMotion="user"><section className={[shell.hero, shell.screen, styles.hero, className].filter(Boolean).join(" ")}>
    <HeroMesh className={styles.mesh} points={MESH} grain={.18} speed={.55} />
    <motion.div className={styles.copy} variants={heroGroup} initial={animateIn ? "hidden" : false} animate="shown">
      <motion.h1 variants={item} className={[shell.title, styles.title].join(" ")}>Her liranın nasıl hareket ettiğini görün</motion.h1>
      <motion.p variants={item} className={[shell.description, styles.description].join(" ")}>Parıltı ödeme sağlayıcınızı, CRM sisteminizi ve veri ambarınızı bağlar; aylık gelirdeki her değişimi olduğu anda açıklar. SQL yok, eskimiş tablo yok.</motion.p>
      <motion.div variants={item} className={styles.actions}>
        <ActionLink action={primaryAction} kind="primary" />
        <ActionLink action={secondaryAction} kind="secondary" />
      </motion.div>
      <motion.p variants={item} className={styles.fine}>14 gün ücretsiz. Yaklaşık dört dakikada bağlanır.</motion.p>
    </motion.div>

    <motion.div
      ref={stage}
      className={styles.stage}
      initial={animateIn ? { opacity: 0, y: 56 } : false}
      animate={{ opacity: 1, y: 0 }}
      transition={calm ? { duration: motionTokens.duration.standard } : { duration: 1.1, ease: [...motionTokens.ease.enter], delay: .32 }}
    >
      <div className={styles.glow} aria-hidden="true" />
      <div className={styles.perspective}>
        <motion.div
          className={styles.tilt}
          style={{ width: box.width * box.scale, height: height * box.scale }}
          initial={animateIn ? { rotateX: 22, scale: .94 } : false}
          animate={{ rotateX: 0, scale: 1 }}
          transition={{ duration: 1.5, ease: [...motionTokens.ease.enter], delay: .36 }}
        >
          {/* Ölçek bir CSS dönüşümü değil Motion değeridir; böylece içerideki yerleşim animasyonları (tarih aralığı vurgusu)
              onun içinden yansıtılır ve her ekran genişliğinde seçenekler arasında tam oturarak kayar. */}
          <motion.div className={styles.scaler} style={{ width: box.width, height, scale: box.scale, originX: 0, originY: 0 }}>
            <LumenDashboard narrow={narrow} userName={userName} userRole={userRole} userAvatarSrc={userAvatarSrc} />
          </motion.div>
        </motion.div>
      </div>
    </motion.div>
  </section></MotionConfig>;
}

/** Parıltı uygulama penceresi. Aralık denetimi dışında her şey içeriktir; denetim bütün ekranın gösterdiği veriyi değiştirir. */
function LumenDashboard({ narrow, userName, userRole, userAvatarSrc }: { narrow: boolean; userName: string; userRole: string; userAvatarSrc?: string | undefined }) {
  const [range, setRange] = useState<LumenRange>("30d");
  const insight = lumenInsight[range];
  return <div className={styles.window} data-narrow={narrow || undefined} role="group" aria-label="Parıltı gelir panosu, örnek veri">
    <div className={styles.chrome} aria-hidden="true">
      <span className={styles.lights}><i /><i /><i /></span>
      <span className={styles.url}>panel.parilti.example/ornek/genel-bakis</span>
    </div>
    <div className={styles.app}>
      {!narrow && <aside className={styles.sidebar}>
        <div className={styles.workspace}>
          <span className={styles.wsMark}>Ö</span>
          <span className={styles.wsName}>Örnek Bulut</span>
          <ChevronsUpDown size={14} strokeWidth={1.75} className={styles.dim} />
        </div>
        <div className={styles.search}><Search size={14} strokeWidth={1.75} />Ara<kbd>⌘K</kbd></div>
        <div className={styles.nav}>
          {NAV.map(({ label, icon: Icon, active }) => <div key={label} className={styles.navItem} data-active={active || undefined}><Icon size={15} strokeWidth={1.75} />{label}</div>)}
        </div>
        <div className={styles.groupLabel}>Kayıtlı görünümler</div>
        <div className={styles.nav}>
          {VIEWS.map(view => <div key={view.label} className={styles.navItem}><i className={styles.dot} data-tone={view.tone} />{view.label}</div>)}
        </div>
        <div className={styles.me}>
          <Avatar name={userName} src={userAvatarSrc} size="sm" />
          <span><strong>{userName}</strong><small>{userRole}</small></span>
          <Settings size={15} strokeWidth={1.75} className={styles.dim} />
        </div>
      </aside>}
      <div className={styles.main}>
        <header className={styles.head}>
          <div>
            <h2 className={styles.h2}>Gelir genel bakışı</h2>
            <p className={styles.sub}>2 dakika önce senkronlandı</p>
          </div>
          <SegmentedControl label="Tarih aralığı" options={lumenRanges} value={range} onValueChange={value => setRange(value as LumenRange)} className={styles.range} />
        </header>

        <div className={styles.kpis}>
          {lumenKpis.map(kpi => {
            const now = kpi.byRange[range];
            return <div key={kpi.id} className={styles.kpi}>
              <Sparkline label={kpi.label} value={now.value} change={now.change} data={now.data} tone={kpi.tone} width={220} height={34} interactive={false} />
            </div>;
          })}
        </div>

        <div className={styles.grid}>
          <div className={styles.card}>
            <div className={styles.cardHead}>
              <p className={styles.insight}><Sparkles size={15} strokeWidth={1.75} className={styles.insightIcon} /><span><strong>{insight.lead}</strong> {insight.rest}</span></p>
              <div className={styles.legend} aria-hidden="true"><span><i className={styles.swatch} />Bu dönem</span><span><i className={styles.swatch} data-last="" />Önceki dönem</span></div>
            </div>
            <LineChart
              label="Net yeni aylık gelir"
              data={lumenSeries[range]}
              series={[{ key: "mrr", label: "Bu dönem", area: true }, { key: "last", label: "Önceki dönem", dashed: true }]}
              height={narrow ? 210 : 232}
              legend={false}
              formatValue={value => formatMoney(value)}
              formatTick={compact}
            />
          </div>
          {!narrow && <div className={styles.card}>
            <div className={styles.cardTitle}>En çok değişenler<span>Aylık gelir farkı</span></div>
            <ul className={styles.movers}>
              {lumenMovers.map(mover => <li key={mover.name}>
                <span className={styles.mark} aria-hidden="true">{avatarInitials(mover.name).charAt(0)}</span>
                <span className={styles.who}><strong>{mover.name}</strong><small>{mover.change}</small></span>
                <span className={styles.amount} data-down={mover.amount < 0 || undefined}>{mover.amount < 0 ? "−" : "+"}{formatMoney(Math.abs(mover.amount))}</span>
              </li>)}
            </ul>
          </div>}
        </div>
      </div>
    </div>
  </div>;
}

export default HeroLumen;

/* Tuval, çizildikten sonra kendi CSS çiziminin üstünde solarak belirir; böylece ilk kare yanıp sönmez. */
.mesh { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.canvas { display: block; width: 100%; height: 100%; opacity: 0; transition: opacity var(--duration-considered, .48s) var(--ease-standard); }
.mesh[data-painted] .canvas { opacity: 1; }
@media (prefers-reduced-motion: reduce) { .canvas { transition: none; } }

"use client";

import { useEffect, useRef } from "react";
import type { CSSProperties } from "react";
import { useReducedMotion } from "motion/react";
import styles from "./hero-mesh.module.css";

/**
 * Bir ağın bir noktası, Gradient mesh düzenleyicisinin kaydettiği modelde: kutunun kesri olarak konum (sol üstten 0 ile 1 arası)
 * ve bir erim. Renk burada verilmez: öğe üzerindeki `--mesh-{n}` CSS değişkeninden okunur, böylece açık ve koyu temalar
 * paletlerini CSS'te ayrı yazar ve tuval, tema değişince yeniden bağlanmadan onu izler.
 */
export interface HeroMeshPoint {
  x: number;
  y: number;
  /** Rengin kutunun kesri olarak erimi, 0,15 ile 1,2 arası. */
  spread: number;
}

export interface HeroMeshProps {
  points: readonly HeroMeshPoint[];
  /** Film greni, 0 ile 1 arası. */
  grain?: number | undefined;
  /** Kayma hızı. 1, 20 saniyede bir döner; 0 ağı durağan tutar. */
  speed?: number | undefined;
  className?: string | undefined;
  style?: CSSProperties | undefined;
}

type Rgb = [number, number, number];

/** Gradient mesh düzenleyicisiyle aynı döngü: tam sayı frekanslar, böylece kayma dikişsizdir. */
const PERIOD = 20, TRAVEL = .075, BREATH = .08, MAX = 8;
/** Kayma yavaştır; saniyede otuz kare altmıştan ayırt edilmez ve maliyeti yarıya indirir. */
const FRAME = 1000 / 30;

const VS = `attribute vec2 a; void main() { gl_Position = vec4(a, 0.0, 1.0); }`;
const FS = `
precision mediump float;
uniform vec2 uRes;
uniform vec3 uBase;
uniform vec4 uP[${MAX}];
uniform vec3 uC[${MAX}];
uniform int uN;
uniform float uGrain;
float hash(vec2 p) { vec3 q = fract(vec3(p.xyx) * .1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }
void main() {
  vec2 uv = vec2(gl_FragCoord.x / uRes.x, 1.0 - gl_FragCoord.y / uRes.y);
  vec3 col = uBase;
  for (int i = 0; i < ${MAX}; i++) {
    if (i >= uN) break;
    vec4 p = uP[i];
    float d = length((uv - p.xy) / max(p.z, 1e-4));
    col = mix(col, uC[i], 1.0 - smoothstep(0.0, 1.0, d));
  }
  float n = hash(floor(gl_FragCoord.xy)) + hash(floor(gl_FragCoord.xy) + 19.19) - 1.0;
  float lum = dot(col, vec3(.2126, .7152, .0722));
  col += n * (uGrain * .1 * (.55 + 1.8 * lum * (1.0 - lum)) + .6 / 255.0);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}`;

function hashOf(text: string) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) { h ^= text.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

const UNIFORMS = ["uRes", "uBase", "uP", "uC", "uN", "uGrain"] as const;

/** Herhangi bir CSS rengini (hex, oklch, color-mix) bir pikselli 2B tuval üzerinden sRGB'ye çevirir. */
function toRgb(color: string, scratch: CanvasRenderingContext2D): Rgb {
  scratch.clearRect(0, 0, 1, 1);
  scratch.fillStyle = "#000";
  scratch.fillStyle = color;
  scratch.fillRect(0, 0, 1, 1);
  const [r = 0, g = 0, b = 0] = scratch.getImageData(0, 0, 1, 1).data;
  return [r / 255, g / 255, b / 255];
}

/** Aynı ağın durağan CSS çizimi: sunucuda, tuval boyanmadan önce ve WebGL yoksa gösterilir. */
function cssMesh(points: readonly HeroMeshPoint[]): CSSProperties {
  const stops = [0, .2, .4, .6, .8, 1].map(t => [t, Math.round((1 - t * t * (3 - 2 * t)) * 100)] as const);
  const layers = points.map((p, i) => `radial-gradient(ellipse ${p.spread * 100}% ${p.spread * 100}% at ${p.x * 100}% ${p.y * 100}%, ${stops.map(([t, a]) => `color-mix(in srgb, var(--mesh-${i + 1}) ${a}%, transparent) ${t * 100}%`).join(", ")})`);
  return { backgroundColor: "var(--mesh-base)", backgroundImage: layers.reverse().join(", ") };
}

/**
 * Gradient mesh'in sade, düzenlemesiz çizimi: tek bir WebGL üçgeni her noktayı bir öncekinin üstüne düzenleyicinin
 * smoothstep sönümü ve greniyle bindirir, düzenleyicinin dikişsiz döngüsünde kayar. Yalnız ekrandayken ve sekme görünürken
 * saniyede otuz kare çizer; azaltılmış harekette tek durağan kare çizer.
 */
export function HeroMesh({ points, grain = .35, speed = 1, className, style }: HeroMeshProps) {
  const root = useRef<HTMLDivElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const reduced = !!useReducedMotion();
  const key = JSON.stringify(points);

  useEffect(() => {
    const host = root.current, node = canvas.current;
    if (!host || !node) return;
    const gl = node.getContext("webgl", { alpha: false, antialias: false, depth: false, stencil: false, powerPreference: "low-power" });
    const scratch = document.createElement("canvas").getContext("2d", { willReadFrequently: true });
    if (!gl || !scratch) return;
    const compile = (type: number, src: string) => { const s = gl.createShader(type)!; gl.shaderSource(s, src); gl.compileShader(s); return s; };
    const prog = gl.createProgram()!;
    gl.attachShader(prog, compile(gl.VERTEX_SHADER, VS));
    gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, FS));
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return;
    gl.useProgram(prog);
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    const loc = gl.getAttribLocation(prog, "a");
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
    const u = Object.fromEntries(UNIFORMS.map(name => [name, gl.getUniformLocation(prog, name)])) as Record<(typeof UNIFORMS)[number], WebGLUniformLocation | null>;

    const pts = (JSON.parse(key) as HeroMeshPoint[]).slice(0, MAX);
    const drift = pts.map((_, i) => { const h = hashOf(`mesh-${i}`); return { ph1: (h % 628) / 100, ph2: ((h >>> 10) % 628) / 100, k1: 1 + ((h >>> 20) % 2), k2: 1 + ((h >>> 22) % 2) }; });
    const P = new Float32Array(MAX * 4), C = new Float32Array(MAX * 3);
    let base: Rgb = [1, 1, 1];

    const readColors = () => {
      const css = getComputedStyle(host);
      base = toRgb(css.getPropertyValue("--mesh-base").trim() || "#fff", scratch);
      pts.forEach((_, i) => { const c = toRgb(css.getPropertyValue(`--mesh-${i + 1}`).trim() || "#fff", scratch); C.set(c, i * 3); });
    };

    let width = 0, height = 0;
    const size = () => {
      // Ağda grenden ince ayrıntı yok; bu yüzden her ekranda CSS pikseli başına bir tuval pikseli yeter.
      width = Math.max(1, Math.round(host.clientWidth));
      height = Math.max(1, Math.round(host.clientHeight));
      node.width = width; node.height = height;
    };

    let t = hashOf(key) % PERIOD;
    const draw = () => {
      const a = (2 * Math.PI * t) / PERIOD;
      pts.forEach((p, i) => {
        const d = drift[i]!;
        P[i * 4] = p.x + TRAVEL * Math.sin(a * d.k1 + d.ph1);
        P[i * 4 + 1] = p.y + TRAVEL * Math.cos(a * d.k2 + d.ph2);
        P[i * 4 + 2] = p.spread * (1 + BREATH * Math.sin(a + d.ph1 * .7));
      });
      gl.viewport(0, 0, width, height);
      gl.uniform2f(u.uRes, width, height);
      gl.uniform3f(u.uBase, base[0], base[1], base[2]);
      gl.uniform4fv(u.uP, P);
      gl.uniform3fv(u.uC, C);
      gl.uniform1i(u.uN, pts.length);
      gl.uniform1f(u.uGrain, grain);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      host.dataset.painted = "";
    };

    readColors();
    size();
    draw();

    const moving = !reduced && speed > 0;
    let visible = false, frame = 0, last = 0;
    const tick = (now: number) => {
      frame = requestAnimationFrame(tick);
      if (now - last < FRAME) return;
      const dt = last ? Math.min(.1, (now - last) / 1000) : 0;
      last = now;
      t = (t + dt * speed) % PERIOD;
      draw();
    };
    const sync = () => {
      const run = moving && visible && document.visibilityState === "visible";
      if (run && !frame) { last = 0; frame = requestAnimationFrame(tick); }
      if (!run && frame) { cancelAnimationFrame(frame); frame = 0; }
    };
    const io = new IntersectionObserver(([entry]) => { if (!entry) return; visible = entry.isIntersecting; sync(); });
    io.observe(host);
    const ro = new ResizeObserver(() => { size(); draw(); });
    ro.observe(host);
    const theme = () => { readColors(); draw(); };
    const mo = new MutationObserver(theme);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme", "data-accent", "class"] });
    const scheme = matchMedia("(prefers-color-scheme: dark)");
    scheme.addEventListener("change", theme);
    document.addEventListener("visibilitychange", sync);
    return () => {
      cancelAnimationFrame(frame);
      io.disconnect(); ro.disconnect(); mo.disconnect();
      scheme.removeEventListener("change", theme);
      document.removeEventListener("visibilitychange", sync);
      delete host.dataset.painted;
    };
  }, [key, grain, speed, reduced]);

  return <div ref={root} className={[styles.mesh, className].filter(Boolean).join(" ")} style={{ ...cssMesh(points), ...style }} aria-hidden="true">
    <canvas ref={canvas} className={styles.canvas} />
  </div>;
}

export default HeroMesh;

